export type WerkbakId = typeof werkbakken[number]['externalIdentifier'];
export type WerkbakNaam = typeof werkbakken[number]['name'];

const defaultWerkbakFlags: Omit<Werkbak, 'externalIdentifier' | 'name' | 'isGeneralInbox'> = {
    releaseComByDefaultWhenLinking: false,
    isForPolicyCommunications: false,
    isForUnlinkedCommunications: false,
    isForIntermediaryCommunications: false,
};

export function vindWerkbak(targetName: string, by: WerkbakLookupKey = 'name'): Werkbak {
    const werkbak = werkbakken.find((w) => w[by] === targetName);
    if (!werkbak) {
        throw new Error(`Werkbak with ${by} "${targetName}" not found.`);
    }

    return {
        ...werkbak,
        ...defaultWerkbakFlags,
        isGeneralInbox: werkbak.externalIdentifier === 'Algemeen',
    };
}